/**
 * 4. Unggah Dokumen Susulan (Model A, Bukti Tambahan, Putusan) LANGSUNG ke Folder Pihak Terkait
 */
function simpanDokumenSusulanPerPihak(ss, payload) {
  var namaPihak = sanitizeName(payload.namaPihakTerkait || "Pihak_Terkait").toUpperCase();
  var kategoriFolder = payload.kategoriFolder || "01_Laporan_Pelanggaran";
  var partyFolderName = payload.partyFolderName || ("Pihak - " + namaPihak);
  var caseFolderName = payload.caseFolderName || sanitizeName(payload.nomorPerkara || ("Perkara_" + Date.now()));
  var subCategoryFolder = payload.subCategoryFolder || "03_Dokumen_Tambahan";

  var structure = getOrCreatePartyFolderStructure(
    payload.driveFolderId || ROOT_DRIVE_FOLDER_ID,
    kategoriFolder,
    partyFolderName,
    caseFolderName
  );
  var targetSubFolder = getOrCreateSubFolder(structure.caseFolder, subCategoryFolder);

  var rawFileName = payload.fileName || (payload.documentLabel || "Dokumen") + ".pdf";
  var prefixedFileName = "[" + namaPihak + "]_" + sanitizeName(rawFileName);
  var fileUrl = targetSubFolder.getUrl();
  var fileId = "";
  var actualFileName = prefixedFileName;

  if (payload.fileData && String(payload.fileData).indexOf("base64,") !== -1) {
    var created = saveBase64FileToFolder(targetSubFolder, payload.fileData, prefixedFileName, payload.fileType);
    if (created) {
      fileId = created.getId();
      fileUrl = created.getUrl();
      actualFileName = created.getName();
    }
  } else {
    var metaContent =
      "Dokumen Terdaftar: " + (payload.documentLabel || rawFileName) + "\\n" +
      "Nama Pihak Terkait: " + namaPihak + "\\n" +
      "Nomor Perkara: " + (payload.nomorPerkara || "-") + "\\n" +
      "Petugas: " + (payload.petugas || "-") + "\\n" +
      "Keterangan: " + (payload.keterangan || "-");
    var txt = upsertTextFile(targetSubFolder, prefixedFileName + ".txt", metaContent, MimeType.PLAIN_TEXT);
    if (txt) {
      fileId = txt.getId();
      fileUrl = txt.getUrl();
      actualFileName = txt.getName();
    }
  }

  var logSheet = getOrCreateSheet(ss, "Log_Arsip_Dokumen_Drive");
  if (logSheet.getLastRow() === 0) {
    logSheet.appendRow([
      "Waktu", "Aksi", "Nomor Perkara", "Nama Pihak Terkait", "Folder Pihak Terkait",
      "Subfolder", "Jenis Dokumen", "Nama File", "File ID Drive", "Petugas", "Tautan File/Folder Drive"
    ]);
    formatHeaderRow(logSheet, "#0F766E");
  }

  logSheet.appendRow([
    new Date().toLocaleString("id-ID", { timeZone: "Asia/Jakarta" }),
    "UPLOAD",
    payload.nomorPerkara || "-",
    namaPihak,
    kategoriFolder + "/" + partyFolderName + "/" + caseFolderName,
    subCategoryFolder,
    payload.documentLabel || "-",
    actualFileName,
    fileId || "-",
    payload.petugas || "-",
    fileUrl
  ]);

  return {
    partyFolder: partyFolderName,
    subFolder: subCategoryFolder,
    folderId: structure.caseFolder.getId(),
    folderUrl: targetSubFolder.getUrl(),
    caseFolderUrl: structure.caseFolder.getUrl(),
    fileId: fileId,
    fileUrl: fileUrl,
    driveFileName: actualFileName
  };
}

/**
 * 5. HAPUS FILE DI GOOGLE DRIVE OTOMATIS (saat user menghapus dokumen/bukti di aplikasi)
 */
function hapusFileDiDrive(ss, payload) {
  var deletedCount = 0;
  var deletedNames = [];

  // Cara 1 (Utama): Hapus langsung berdasarkan Google Drive File ID
  if (payload.fileId && String(payload.fileId).trim() !== "") {
    try {
      var targetFile = DriveApp.getFileById(String(payload.fileId).trim());
      if (!targetFile.isTrashed()) {
        deletedNames.push(targetFile.getName());
        targetFile.setTrashed(true);
        deletedCount++;
      }
    } catch (e) {
      // Lanjut ke pencarian berdasarkan nama folder & nama file
    }
  }

  // Cara 2 (Fallback berdasarkan struktur folder & nama file)
  if (deletedCount === 0 && payload.fileName) {
    try {
      var folder = findExistingSubFolderPath(
        payload.driveFolderId || ROOT_DRIVE_FOLDER_ID,
        [
          payload.kategoriFolder || "01_Laporan_Pelanggaran",
          payload.partyFolderName,
          payload.caseFolderName,
          payload.subCategoryFolder
        ]
      );

      if (folder) {
        var namaPihak = sanitizeName(payload.namaPihakTerkait || "").toUpperCase();
        var candidates = [];
        if (payload.driveFileName) candidates.push(sanitizeName(payload.driveFileName));
        if (payload.fileName) {
          candidates.push(sanitizeName(payload.fileName));
          if (namaPihak) {
            candidates.push(sanitizeName("[" + namaPihak + "]_" + payload.fileName));
            candidates.push(sanitizeName("[" + namaPihak + "]_" + payload.fileName + ".txt"));
          }
        }

        var files = folder.getFiles();
        while (files.hasNext()) {
          var f = files.next();
          var fname = f.getName();
          var matched = false;
          for (var i = 0; i < candidates.length; i++) {
            if (candidates[i] && (fname === candidates[i] || fname.indexOf(sanitizeName(payload.fileName)) !== -1)) {
              matched = true;
              break;
            }
          }
          if (matched && !f.isTrashed()) {
            deletedNames.push(fname);
            f.setTrashed(true);
            deletedCount++;
          }
        }
      }
    } catch (err) {
      // ignore fallback search errors
    }
  }

  // Catat penghapusan di sheet log
  try {
    var logSheet = getOrCreateSheet(ss, "Log_Arsip_Dokumen_Drive");
    if (logSheet.getLastRow() === 0) {
      logSheet.appendRow([
        "Waktu", "Aksi", "Nomor Perkara", "Nama Pihak Terkait", "Folder Pihak Terkait",
        "Subfolder", "Jenis Dokumen", "Nama File", "File ID Drive", "Petugas", "Tautan File/Folder Drive"
      ]);
      formatHeaderRow(logSheet, "#0F766E");
    }
    logSheet.appendRow([
      new Date().toLocaleString("id-ID", { timeZone: "Asia/Jakarta" }),
      "HAPUS_FILE",
      payload.nomorPerkara || "-",
      payload.namaPihakTerkait || "-",
      (payload.kategoriFolder || "") + "/" + (payload.partyFolderName || "") + "/" + (payload.caseFolderName || ""),
      payload.subCategoryFolder || "-",
      payload.documentLabel || "-",
      deletedNames.join(", ") || payload.driveFileName || payload.fileName || "-",
      payload.fileId || "-",
      payload.petugas || "Operator Aplikasi",
      "Dihapus (Trashed: " + deletedCount + " file)"
    ]);
  } catch (e) {
    // ignore log sheet failure
  }

  return { deletedCount: deletedCount, deletedNames: deletedNames };
}

/**
 * 6. HAPUS FOLDER PERKARA & SELURUH FILE DI GOOGLE DRIVE OTOMATIS
 *    (saat user menghapus Laporan, Temuan, atau Permohonan Sengketa melalui aplikasi)
 */
function hapusFolderPerkaraDiDrive(ss, payload) {
  var trashedFolders = 0;
  var trashedFiles = 0;

  // 1. Hapus daftar file ID individual jika dikirim
  if (payload.fileIds && payload.fileIds.length > 0) {
    payload.fileIds.forEach(function(fid) {
      if (!fid) return;
      try {
        var f = DriveApp.getFileById(String(fid).trim());
        if (!f.isTrashed()) {
          f.setTrashed(true);
          trashedFiles++;
        }
      } catch (e) {
        // ignore if already trashed or not found
      }
    });
  }

  // 2. Hapus folder perkara berdasarkan caseFolderId jika tersedia
  if (payload.caseFolderId && String(payload.caseFolderId).trim() !== "") {
    try {
      var caseDir = DriveApp.getFolderById(String(payload.caseFolderId).trim());
      if (!caseDir.isTrashed()) {
        caseDir.setTrashed(true);
        trashedFolders++;
      }
    } catch (e) {
      // lanjut fallback pencarian nama folder
    }
  }

  // 3. Fallback: cari folder perkara berdasarkan kategoriFolder / partyFolderName / caseFolderName
  if (trashedFolders === 0 && payload.partyFolderName && payload.caseFolderName) {
    try {
      var partyDir = findExistingSubFolderPath(
        payload.driveFolderId || ROOT_DRIVE_FOLDER_ID,
        [payload.kategoriFolder || "01_Laporan_Pelanggaran", payload.partyFolderName]
      );
      if (partyDir) {
        var cleanCaseName = sanitizeName(payload.caseFolderName);
        var caseIter = partyDir.getFoldersByName(cleanCaseName);
        while (caseIter.hasNext()) {
          var cFolder = caseIter.next();
          if (!cFolder.isTrashed()) {
            cFolder.setTrashed(true);
            trashedFolders++;
          }
        }
        // Jika folder pihak terkait sudah kosong (tidak ada perkara lain), bersihkan juga
        if (!partyDir.getFolders().hasNext() && !partyDir.getFiles().hasNext()) {
          partyDir.setTrashed(true);
        }
      }
    } catch (err) {
      // ignore fallback search errors
    }
  }

  // 4. Hapus baris terkait di Google Sheets agar tetap sinkron
  try {
    var sheetName = "Model_B1_Laporan";
    if (payload.modul === "temuan") sheetName = "Model_A2_Temuan";
    else if (payload.modul === "sengketa") sheetName = "Sengketa_PSPP";

    var targetSheet = ss.getSheetByName(sheetName);
    if (targetSheet && payload.nomorPerkara) {
      var rows = targetSheet.getDataRange().getValues();
      for (var r = rows.length - 1; r >= 1; r--) {
        if (String(rows[r][0]).trim() === String(payload.nomorPerkara).trim() ||
            String(rows[r][1]).trim() === String(payload.nomorPerkara).trim()) {
          targetSheet.deleteRow(r + 1);
        }
      }
    }
  } catch (e) {
    // ignore sheet delete error
  }

  return { trashedFolders: trashedFolders, trashedFiles: trashedFiles };
}

/**
 * Helper: Cari folder yang sudah ada tanpa membuat folder baru (untuk operasi hapus)
 */
function findExistingSubFolderPath(parentFolderId, segments) {
  var current = resolveRootDriveFolder(parentFolderId);
  for (var i = 0; i < segments.length; i++) {
    var seg = segments[i];
    if (!seg) continue;
    var clean = sanitizeName(seg);
    var iter = current.getFoldersByName(clean);
    if (!iter.hasNext()) return null;
    current = iter.next();
  }
  return current;
}

function resolveRootDriveFolder(parentFolderId) {
  var idStr = String(parentFolderId || "").trim();
  if (idStr && idStr !== "MASUKKAN_ID_FOLDER_GOOGLE_DRIVE_DI_SINI" && !idStr.startsWith("1Drive_BawasluRiau_")) {
    return DriveApp.getFolderById(idStr);
  }
  return DriveApp.getRootFolder();
}

/**
 * Helper Inti: Struktur Folder Terisolasi per Nama Pihak Terkait (Anti-Duplikasi & Anti-Tercampur)
 * Root -> Kategori Modul -> Folder Nama Pihak Terkait -> Folder Perkara
 */
function getOrCreatePartyFolderStructure(parentFolderId, kategoriFolder, partyFolderName, caseFolderName) {
  var rootFolder = resolveRootDriveFolder(parentFolderId);
  var catFolder = getOrCreateSubFolder(rootFolder, kategoriFolder);
  var partyFolder = getOrCreateSubFolder(catFolder, partyFolderName);
  var caseFolder = getOrCreateSubFolder(partyFolder, caseFolderName);

  return {
    rootFolder: rootFolder,
    catFolder: catFolder,
    partyFolder: partyFolder,
    caseFolder: caseFolder
  };
}

function getOrCreateSubFolder(parentFolder, folderName) {
  var clean = sanitizeName(folderName);
  var existing = parentFolder.getFoldersByName(clean);
  if (existing.hasNext()) {
    return existing.next();
  }
  return parentFolder.createFolder(clean);
}

function saveBase64FileToFolder(folder, dataUrl, fileName, fallbackMimeType) {
  try {
    var parts = String(dataUrl).split("base64,");
    if (parts.length < 2) return null;
    var header = parts[0] || "";
    var mimeMatch = header.match(/data:([^;]+);/i);
    var contentType = (mimeMatch && mimeMatch[1]) ? mimeMatch[1] : (fallbackMimeType || "application/octet-stream");
    var decoded = Utilities.base64Decode(parts[1]);
    var cleanFileName = sanitizeName(fileName);
    var existing = folder.getFilesByName(cleanFileName);
    while (existing.hasNext()) {
      existing.next().setTrashed(true);
    }
    var blob = Utilities.newBlob(decoded, contentType, cleanFileName);
    return folder.createFile(blob);
  } catch (err) {
    throw new Error("Gagal decode/simpan file " + fileName + ": " + err.toString());
  }
}

function stripFileDataForJson(obj) {
  try {
    return JSON.parse(JSON.stringify(obj, function(key, value) {
      if (key === "fileData" && typeof value === "string" && value.indexOf("data:") === 0) {
        return "[STORED_IN_GOOGLE_DRIVE]";
      }
      return value;
    }));
  } catch (e) {
    return {};
  }
}

function upsertTextFile(folder, fileName, content, mimeType) {
  var cleanFileName = sanitizeName(fileName);
  var existing = folder.getFilesByName(cleanFileName);
  while (existing.hasNext()) {
    existing.next().setTrashed(true);
  }
  return folder.createFile(cleanFileName, content, mimeType);
}

function sanitizeName(str) {
  return String(str || "Tanpa_Nama")
    .trim()
    .replace(/[\\/\\\\?%*:|"<>]/g, " ")
    .replace(/\\s+/g, " ");
}

function openTargetSpreadsheet(customSpreadsheetId) {
  if (customSpreadsheetId && String(customSpreadsheetId).trim() !== "" && !String(customSpreadsheetId).startsWith("1BawasluRiau_")) {
    try {
      return SpreadsheetApp.openById(String(customSpreadsheetId).trim());
    } catch (err) {
      return SpreadsheetApp.getActiveSpreadsheet();
    }
  }
  return SpreadsheetApp.getActiveSpreadsheet();
}

function getOrCreateSheet(ss, sheetName) {
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
  }
  return sheet;
}

function formatHeaderRow(sheet, hexColor) {
  var headerRange = sheet.getRange(1, 1, 1, sheet.getLastColumn());
  headerRange.setBackground(hexColor);
  headerRange.setFontColor("#FFFFFF");
  headerRange.setFontWeight("bold");
  headerRange.setFontFamily("Arial");
  headerRange.setFontSize(10);
  headerRange.setHorizontalAlignment("center");
  sheet.setFrozenRows(1);
}

function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}
